        return amountCurrency6;
    const oracleRateKey = {
        CAD: 'usdcad',
        EUR: 'usdeur',
        JPY: 'usdjpy',
        CNY: 'usdcny',
        HKD: 'usdhkd',
        SGD: 'usdsgd',
        TWD: 'usdtwd',
    };
    const rateKey = oracleRateKey[cur];
