function collectEthersRevertDataHex(e) {
    let cur = e;
    const seen = new Set();
    for (let i = 0; i < 12 && cur != null && !seen.has(cur); i++) {
        seen.add(cur);
        const o = cur;
        const d = o['data'];
        if (typeof d === 'string' && d.startsWith('0x') && d.length >= 10)
            return d.toLowerCase();
        const err = o['error'];
        const ed = err?.['data'];
        if (typeof ed === 'string' && ed.startsWith('0x') && ed.length >= 10)
            return ed.toLowerCase();
        const info = o['info'];
        const ie = info?.['error'];
        const ied = ie?.['data'];
        if (typeof ied === 'string' && ied.startsWith('0x') && ied.length >= 10)
            return ied.toLowerCase();
        cur = o['cause'] ?? o['error'];
    }
    const msg = String(e?.message ?? e ?? '');
    const m = msg.match(/data="(0x[a-fA-F0-9]+)"/);
    if (m)
        return m[1].toLowerCase();
    return '';
}
