const aaInstitutionalV2RelayProcess = async () => {
    const obj = exports.aaInstitutionalV2RelayPool.shift();
    if (!obj)
        return;
    const SC = (0, settleContractPool_1.shiftSettleConet)();
    if (!SC) {
        exports.aaInstitutionalV2RelayPool.unshift(obj);
        return setTimeout(() => kickAaInstitutionalV2RelayProcess(), 3000);
    }
    const respond = (status, body) => {
        if (obj.res && !obj.res.headersSent) {
            obj.res.status(status).json(body).end();
        }
    };
    try {
        const { AA_V2_FACTORY_ABI } = await import('./aaInstitutionalV2Multisig.js');
        const factory = new ethers_1.ethers.Contract(ethers_1.ethers.getAddress(chainAddresses_1.BEAMIO_AA_FACTORY_V2), AA_V2_FACTORY_ABI, SC.walletConet);
        const isPm = !!(await factory.isPayMaster(SC.walletConet.address));
        if (!isPm) {
            respond(500, {
                success: false,
                error: `Settle wallet ${SC.walletConet.address} is not a V2 Factory paymaster`,
            });
            return;
        }
        if (obj.kind === 'proposeTransfer') {
            const b = obj.body;
            const tx = await factory.proposeTransfer(b.account, b.token, b.to, BigInt(b.amount), b.deadline, b.nonce, b.signature);
            const receipt = await tx.wait();
            if (!receipt || Number(receipt.status) === 0) {
                respond(500, { success: false, error: 'proposeTransfer reverted', txHash: tx.hash });
                return;
            }
            const taskId = parseInstitutionalAaV2TaskIdFromReceipt(receipt, b.account);
            if (!taskId) {
                respond(500, {
                    success: false,
                    error: 'proposeTransfer confirmed but TaskProposed event not found',
                    txHash: tx.hash,
                });
                return;
            }
            respond(200, { success: true, txHash: tx.hash, taskId });
            return;
        }
        if (obj.kind === 'proposeSetPolicy') {
            const b = obj.body;
            const tx = await factory.proposeSetPolicy(b.account, b.managersSorted, b.newThreshold, b.deadline, b.nonce, b.signature);
            const receipt = await tx.wait();
            if (!receipt || Number(receipt.status) === 0) {
                respond(500, { success: false, error: 'proposeSetPolicy reverted', txHash: tx.hash });
                return;
            }
            const taskId = parseInstitutionalAaV2TaskIdFromReceipt(receipt, b.account);
            if (!taskId) {
                respond(500, {
                    success: false,
                    error: 'proposeSetPolicy confirmed but TaskProposed event not found',
                    txHash: tx.hash,
                });
                return;
            }
            respond(200, { success: true, txHash: tx.hash, taskId });
            return;
        }
        if (obj.kind === 'vote') {
            const b = obj.body;
            const tx = await factory.vote(b.account, BigInt(b.taskId), b.approve, b.deadline, b.nonce, b.signature);
            const receipt = await tx.wait();
            if (!receipt || Number(receipt.status) === 0) {
                respond(500, { success: false, error: 'vote reverted', txHash: tx.hash });
                return;
            }
            respond(200, { success: true, txHash: tx.hash, taskId: b.taskId });
            return;
        }
        respond(400, { success: false, error: 'Unknown relay kind' });
    }
    catch (e) {
        const err = e;
        (0, logger_1.logger)(safe_1.default.yellow(`[aaInstitutionalV2Relay] failed: ${err?.shortMessage ?? err?.message ?? String(e)}`));
        respond(500, { success: false, error: err?.shortMessage ?? err?.message ?? String(e) });
    }
    finally {
        (0, settleContractPool_1.unshiftSettleConet)(SC);
        if (exports.aaInstitutionalV2RelayPool.length > 0) {
            setTimeout(() => kickAaInstitutionalV2RelayProcess(), 1000);
        }
    }
};
exports.aaInstitutionalV2RelayProcess = aaInstitutionalV2RelayProcess;
