function asBigInt(v, fallback = 0n) {
    try {
        if (typeof v === 'bigint')
            return v;
        if (typeof v === 'number')
            return BigInt(v);
        if (typeof v === 'string') {
            if (v.startsWith('0x'))
                return BigInt(v);
            if (v.trim() === '')
                return fallback;
            return BigInt(v);
        }
        return fallback;
    }
    catch {
        return fallback;
    }
}
function hexBytesLen(hex) {
    if (!hex || typeof hex !== 'string')
        return 0;
    if (!hex.startsWith('0x'))
        return 0;
    return (hex.length - 2) / 2;
}
