async function verifyCardOpenTransferSignature(payload) {
    try {
        const env = settleContractPool_1.Settle_ContractPool[0];
        const factory = env?.baseFactoryPaymaster;
        if (!factory)
            return { ok: false, error: 'Factory not configured' };
        const factoryAddr = await factory.getAddress();
        const provider = factory.runner.provider;
        const chainId = (await provider.getNetwork()).chainId;
        const encoded = ethers_1.ethers.AbiCoder.defaultAbiCoder().encode(['string', 'address', 'address', 'uint256', 'address', 'uint256', 'uint256', 'uint256', 'uint256', 'bytes32'], [
            'OpenTransfer',
            factoryAddr,
            ethers_1.ethers.getAddress(payload.cardAddress),
            chainId,
            ethers_1.ethers.getAddress(payload.fromEOA),
            BigInt(payload.id),
            BigInt(payload.maxAmount),
            BigInt(payload.validAfter),
            BigInt(payload.validBefore),
            payload.nonce,
        ]);
        const hash = ethers_1.ethers.keccak256(encoded);
        const recovered = ethers_1.ethers.verifyMessage(ethers_1.ethers.getBytes(hash), payload.signature);
        if (recovered.toLowerCase() !== ethers_1.ethers.getAddress(payload.fromEOA).toLowerCase()) {
            return { ok: false, error: 'Invalid OpenTransfer signature' };
        }
        if (BigInt(payload.amount) <= 0n || BigInt(payload.amount) > BigInt(payload.maxAmount)) {
            return { ok: false, error: 'Amount exceeds signed maximum' };
        }
        const now = BigInt(Math.floor(Date.now() / 1000));
        if (now < BigInt(payload.validAfter) || now > BigInt(payload.validBefore)) {
            return { ok: false, error: 'Signature expired' };
        }
        return { ok: true };
    }
    catch (e) {
        return { ok: false, error: e?.shortMessage ?? e?.message ?? 'Signature verification failed' };
    }
}
